 $page=max(1,(int)($_GET['page']??1));$count=(int)q('SELECT COUNT(*) FROM registrations r WHERE '.implode(' AND ',$where),$args)->fetchColumn();$offset=($page-1)*50;$rows=all('SELECT r.*,e.name event_name FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where).' ORDER BY r.id DESC LIMIT 50 OFFSET '.$offset,$args); ?>
 <div class="card p-4"><form method="get"><input type="hidden" name="p" value="registrations"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column($events,'name','id'),(string)$eventId);?></div><div class="col-md-4"><?php field('search','Nombre, apellido, CI o registro',$search,'text',false);?></div><div class="col-md-4"><?php selectField('status','Estado',[''=>'Todos','Pendiente'=>'Pendiente','En revisión'=>'En revisión','Pagado'=>'Pagado','Rechazado'=>'Rechazado','Anulado'=>'Anulado'],$state);?></div></div><button class="btn btn-primary">Filtrar</button><?php if($eventId):?> <a class="btn btn-success" href="<?=url('p=register&id='.$eventId)?>">Nueva inscripción</a><?php endif?></form></div><div class="card p-3"><p><?=e($count)?> participantes encontrados</p><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Registro</th><th>Participante</th><th>CI</th><th>Evento</th><th>Tipo</th><th>Importe</th><th>Cobrado / debe</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['id'])?></td><td><?=e(nombreParticipante($r))?></td><td><?=e($r['ci'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['category'])?></td><td><?=money($r['price'])?></td><td><?=money($r['monto_cobrado'])?> / <?=money(max(0,$r['price']-$r['monto_cobrado']))?></td><td><?=e($r['status'])?></td><td><a class="btn btn-sm btn-primary" href="<?=url('p=participant&t='.$r['token'])?>">Ver / entregar</a></td></tr><?php endforeach?></tbody></table></div><div><?php if($page>1):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">Anterior</a><?php endif?> <span>Página <?=e($page)?></span><?php if($page*50<$count):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Siguiente</a><?php endif?></div></div><?php footerPage();exit;
}
